const result=document.getElementById("order-result"),formFields=["o-name","o-phone","o-email","o-company","o-project","o-address","o-comment"],invalid=formFields.find(id=>!document.getElementById(id).value.trim());if(invalid){document.getElementById(invalid).focus();result.innerHTML='<div class="form-error">Заполните все поля заявки.</div>';return}const phone=document.getElementById("o-phone").value.trim(),phoneDigits=phone.replace(/\D/g,"");if(phoneDigits.length<7||phoneDigits.length>15){document.getElementById("o-phone").focus();result.innerHTML='<div class="form-error">Введите телефон в международном формате: от 7 до 15 цифр, например +380 67 123 45 67.</div>';return}const payload={customerName:document.getElementById("o-name").value,phone,email:document.getElementById("o-email").value,company:document.getElementById("o-company").value,projectType:document.getElementById("o-project").value,address:document.getElementById("o-address").value,comment:document.getElementById("o-comment").value,items};
